using System.Collections;

string frontendData = "data:image/png;base64,";
// 找到逗号的位置，截取后面的纯数据部分
string base64String = frontendData.Substring(frontendData.IndexOf(",") + 1);

// 这时才能成功转换为图片的二进制字节流
byte[] imageBytes = Convert.FromBase64String(base64String);
await System.IO.File.WriteAllBytesAsync("avatar.png", imageBytes);

string hexString = string.Join("", imageBytes.Select(b => string.Format("{0:X2}", b)));
Console.WriteLine();